// Ollama request: the notes chosen by memory-api, each in a <note number="n">
// tag, and the rules of the answer. Tuned on qwen2.5:3b: the reminder right
// before the question makes it cite the notes far more often.
const system = [
  "You answer the user's question from their personal notes, given below between <note> tags.",
  'Answer in the language of the question, even when the notes are in another language, in a few short sentences.',
  'Every sentence must end with the number of the note it comes from, in brackets. Example: "Le pointage dure 4 heures [1]." Example: "The proofing takes 12 hours [1]."',
  'Use only what the notes say. If they do not answer the question, say that your notes do not cover it. Never invent.',
  'When you answer in French, address the user as « tu ».',
  'Do not repeat the note titles, sections or tags.',
].join('\n');
const { query, context } = $json;
return [{
  json: {
    model: 'qwen2.5:3b',
    stream: false,
    options: { temperature: 0.1 },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: `${context}\n\nQuestion (answer in its language, citing the notes): ${query}` },
    ],
  },
}];

// Keeps only the citations of notes that were given to the model, then
// lists the cited notes (path and title) under the answer.
const sources = $('Relevant notes').first().json.sources;
const byNumber = new Map(sources.map((source) => [source.n, source]));
const cited = new Set();
const text = String($json.message?.content ?? '')
  .replace(/\[(\d+(?:\s*,\s*\d+)*)\]/g, (_match, list) => {
    const numbers = list.split(',').map((n) => Number(n.trim())).filter((n) => byNumber.has(n));
    numbers.forEach((n) => cited.add(n));
    return numbers.length > 0 ? `[${numbers.join(', ')}]` : '';
  })
  .trim();
const used = sources.filter((source) => cited.has(source.n));
const list = (notes) => notes.map((s) => `[${s.n}] ${s.title} (${s.path})`).join('\n');
const footer = used.length > 0
  ? `Sources :\n${list(used)}`
  : `Notes consultées (non citées) :\n${list(sources)}`;
return [{
  json: {
    answer: `${text}\n\n${footer}`,
    found: true,
    cited: used.length > 0,
    sources: (used.length > 0 ? used : sources).map(({ n, path, title, sections }) => ({ n, path, title, sections })),
  },
}];

// No note passed the relevance threshold: say so instead of answering.
return [{
  json: {
    answer: 'Je n\'ai trouvé aucune note pertinente dans ton vault pour cette question.',
    found: false,
    cited: false,
    sources: [],
  },
}];
